fn in_ranges(flat: &[u32], c: char) -> bool {
    let point = u32::from(c);
    let index = flat.partition_point(|bound| *bound <= point);
    index % 2 == 1 || (index > 0 && flat[index - 1] == point)
}

fn mapped(runs: &[(u32, u32, u32, i32)], c: char) -> char {
    let point = u32::from(c);
    let index = runs.partition_point(|(first, ..)| *first <= point);
    let Some((first, count, stride, offset)) = index.checked_sub(1).map(|index| runs[index]) else {
        return c;
    };
    let step = point - first;
    if step % stride != 0 || step / stride >= count {
        return c;
    }
    point
        .checked_add_signed(offset)
        .and_then(char::from_u32)
        .unwrap_or(c)
}

/// Whether `re` counts `c` as a word character in a `str` pattern.
pub fn is_word(c: char) -> bool {
    in_ranges(&WORD, c)
}

pub fn is_cased(c: char) -> bool {
    in_ranges(&CASED, c)
}

/// The simple lowercase mapping `re` folds with under `re.IGNORECASE`.
pub fn to_lower(c: char) -> char {
    mapped(&LOWER, c)
}

/// The uppercase of a character outside the Basic Multilingual Plane; other characters map to themselves.
pub fn to_upper_astral(c: char) -> char {
    mapped(&UPPER_ASTRAL, c)
}

/// The characters besides `lower` itself that fold to the lowercase character `lower`.
pub fn case_fixes(lower: char) -> &'static [u32] {
    let point = u32::from(lower);
    FIXES
        .binary_search_by_key(&point, |(key, _)| *key)
        .map_or(&[], |index| FIXES[index].1)
}

const INT_MAX_STR_DIGITS: usize = 4300;

/// `int(text)`: surrounding whitespace, a sign, and single underscores between digits are allowed. The
/// result is decimal digits with an optional `-`, never `-0`; the error is the `ValueError` message.
pub fn parse_int(text: &str) -> Result<String, String> {
    let invalid = || {
        format!(
            "invalid literal for int() with base 10: {}",
            crate::pytext::repr_str(text)
        )
    };
    let body = crate::pytext::strip(text);
    let (negative, body) = match body.chars().next() {
        Some('-') => (true, &body[1..]),
        Some('+') => (false, &body[1..]),
        _ => (false, body),
    };
    let mut digits = String::new();
    let mut previous_underscore = true;
    for c in body.chars() {
        if c == '_' {
            if previous_underscore {
                return Err(invalid());
            }
            previous_underscore = true;
        } else {
            let value = decimal(c).ok_or_else(invalid)?;
            digits.push(char::from_digit(value, 10).ok_or_else(invalid)?);
            previous_underscore = false;
        }
    }
    if digits.is_empty() || previous_underscore {
        return Err(invalid());
    }
    if digits.len() > INT_MAX_STR_DIGITS {
        return Err(format!(
            "Exceeds the limit ({INT_MAX_STR_DIGITS} digits) for integer string conversion: value has {} digits; use sys.set_int_max_str_digits() to increase the limit",
            digits.len()
        ));
    }
    let trimmed = digits.trim_start_matches('0');
    Ok(match (trimmed.is_empty(), negative) {
        (true, _) => "0".to_string(),
        (false, true) => format!("-{trimmed}"),
        (false, false) => trimmed.to_string(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn digits_are_category_nd() {
        assert_eq!(decimal('7'), Some(7));
        assert_eq!(decimal('\u{0665}'), Some(5));
        assert_eq!(decimal('\u{1FBF9}'), Some(9));
        assert_eq!(decimal('\u{1D7CE}'), Some(0));
        assert_eq!(decimal('\u{1D7D7}'), Some(9));
        assert_eq!(decimal('\u{1D7D8}'), Some(0));
        assert_eq!(decimal('a'), None);
        assert_eq!(decimal('/'), None);
        assert_eq!(decimal(':'), None);
        assert_eq!(decimal('\u{00B2}'), None);
        assert_eq!(decimal('\u{2160}'), None);
    }

    #[test]
    fn int_matches_python() {
        for (text, value) in [
            ("7", "7"),
            (" 7\n", "7"),
            ("+07", "7"),
            ("-0", "0"),
            ("-12", "-12"),
            ("1_000", "1000"),
            ("\u{0663}", "3"),
            ("00", "0"),
        ] {
            assert_eq!(parse_int(text).as_deref(), Ok(value), "{text:?}");
        }
        for text in ["", " ", "_1", "1_", "1__0", "1.0", "0x1", "--1", "+", "1 2"] {
            assert_eq!(
                parse_int(text),
                Err(format!(
                    "invalid literal for int() with base 10: {}",
                    crate::pytext::repr_str(text)
                )),
                "{text:?}"
            );
        }
    }
}
